            (Id(rawValue: stage.componentId(G.Value.self)), G.inOut),
            (Id(rawValue: stage.componentId(H.Value.self)), H.inOut),
        ]
    }

    /// Calls `body` for every row of `iteration`.
    @inlinable
    public static func forEach(_ iteration: Iteration, body: Each) {
        let a = Field<A>(iteration: iteration, index: 0)
        let b = Field<B>(iteration: iteration, index: 1)
        let c = Field<C>(iteration: iteration, index: 2)
        let d = Field<D>(iteration: iteration, index: 3)
        let e = Field<E>(iteration: iteration, index: 4)
        let f = Field<F>(iteration: iteration, index: 5)
        let g = Field<G>(iteration: iteration, index: 6)
        let h = Field<H>(iteration: iteration, index: 7)
        for row in 0..<iteration.count {
            body(
                A.access(a, row: row), B.access(b, row: row), C.access(c, row: row), D.access(d, row: row),
                E.access(e, row: row), F.access(f, row: row), G.access(g, row: row), H.access(h, row: row)
            )
        }
    }

    /// Calls `body` for every row of `iteration` with its entity.
    @inlinable
    public static func forEachEntity(_ iteration: Iteration, body: EachEntity) {
        let a = Field<A>(iteration: iteration, index: 0)
        let b = Field<B>(iteration: iteration, index: 1)
        let c = Field<C>(iteration: iteration, index: 2)
        let d = Field<D>(iteration: iteration, index: 3)
        let e = Field<E>(iteration: iteration, index: 4)
        let f = Field<F>(iteration: iteration, index: 5)
        let g = Field<G>(iteration: iteration, index: 6)
        let h = Field<H>(iteration: iteration, index: 7)
        for row in 0..<iteration.count {
            body(
                iteration.entity(at: row), A.access(a, row: row), B.access(b, row: row), C.access(c, row: row),
                D.access(d, row: row), E.access(e, row: row), F.access(f, row: row), G.access(g, row: row),
                H.access(h, row: row)
            )
        }
    }

    /// Calls `body` for every row of `iteration` with the iteration and its entity.
    @inlinable
    public static func forEachIteration(_ iteration: Iteration, body: EachIteration) {
        let a = Field<A>(iteration: iteration, index: 0)
        let b = Field<B>(iteration: iteration, index: 1)
        let c = Field<C>(iteration: iteration, index: 2)
        let d = Field<D>(iteration: iteration, index: 3)
        let e = Field<E>(iteration: iteration, index: 4)
        let f = Field<F>(iteration: iteration, index: 5)
        let g = Field<G>(iteration: iteration, index: 6)
        let h = Field<H>(iteration: iteration, index: 7)
        for row in 0..<iteration.count {
            body(
                iteration, iteration.entity(at: row), A.access(a, row: row), B.access(b, row: row),
                C.access(c, row: row), D.access(d, row: row), E.access(e, row: row), F.access(f, row: row),
                G.access(g, row: row), H.access(h, row: row)
            )
        }
    }
}

extension World {
    /// Creates a query for entities that have every term's component, narrowed by `filter`.
    ///
    /// - Parameters:
    ///   - a: ``In``, ``InOut`` or ``Out`` of the component the closure needs.
    ///   - filter: Tags, components and pairs the entities must have or must not have.
    /// - Returns: The query, which stays valid until it or the world goes out of scope.
    public func query<A: QueryTerm>(
        _ a: A.Type, filter: [QueryFilter] = []
    ) -> Query<Terms1<A>> {
        makeQuery(filter: filter)
    }

    /// Creates a system: a query whose closure runs once per matched entity every frame, in
    /// `phase`.
    ///
    /// ```swift
    /// world.system(InOut<Position>.self, In<Velocity>.self, name: "Move") { position, velocity in
    ///     position.x += velocity.x
    /// }
    /// ```
    ///
    /// Systems in the same phase run in the order they were created, unless Flecs reorders them
    /// by what they read and write. The closure runs on the thread calling
    /// ``progress(deltaTime:)``; see `parallelSystem` for the multi-threaded kind. Overloads take
    /// a closure that also receives the ``Entity``, or the ``Iteration`` (for the stage and the
    /// time step) and the entity, and the same again for two to eight components.
    ///
    /// - Parameters:
    ///   - a: ``In``, ``InOut`` or ``Out`` of the component the closure needs.
    ///   - name: The system's entity name, shown in the Flecs Explorer and in logs.
    ///   - phase: When in the frame the system runs; one of Flecs' phases such as
    ///     ``Entity/onUpdate``, or a custom one from ``phase(_:after:)``.
    ///   - filter: Tags, components and pairs the entities must have or must not have.
    ///   - body: Called per entity with the accessors for each term.
    /// - Returns: The system's entity, for ``run(_:deltaTime:)``, ``setInterval(_:seconds:)`` and
    ///   ``WorldAccess/setEnabled(_:_:)``.
    @inlinable
    @discardableResult
    public func system<A: QueryTerm>(
        _ a: A.Type, name: String? = nil, phase: Entity = .onUpdate, filter: [QueryFilter] = [],
        each body: @escaping Terms1<A>.Each
    ) -> Entity {
        makeSystem(Terms1<A>.self, name: name, phase: phase, filter: filter, parallel: false) {
            Terms1<A>.forEach($0, body: body)
        }
    }

    /// Creates a system whose closure also receives the entity.
    @inlinable
    @discardableResult
    public func system<A: QueryTerm>(
        _ a: A.Type, name: String? = nil, phase: Entity = .onUpdate, filter: [QueryFilter] = [],
        each body: @escaping Terms1<A>.EachEntity
    ) -> Entity {
        makeSystem(Terms1<A>.self, name: name, phase: phase, filter: filter, parallel: false) {
            Terms1<A>.forEachEntity($0, body: body)
        }
    }

