    @discardableResult
    public func system<A: QueryTerm>(
        _ a: A.Type, name: String? = nil, phase: Entity = .onUpdate, filter: [QueryFilter] = [],
        each body: @escaping Terms1<A>.EachIteration
    ) -> Entity {
        makeSystem(Terms1<A>.self, name: name, phase: phase, filter: filter, parallel: false) {
            Terms1<A>.forEachIteration($0, body: body)
