    /// Creates a system that Flecs splits across the threads from ``setThreads(_:)``.
    ///
    /// The closure must be `@Sendable` and the components `Sendable`, since it runs on several
    /// threads at once, each over its own slice of the matched entities. Where there are no
    /// threads (Wasm, or without ``setThreads(_:)``) it runs like a plain system. See `system`
    /// for the parameters.
    @inlinable
    @discardableResult
    public func parallelSystem<A: QueryTerm>(
        _ a: A.Type, name: String? = nil, phase: Entity = .onUpdate, filter: [QueryFilter] = [],
        each body: @escaping Terms1<A>.SendableEach
    ) -> Entity where A.Value: Sendable {
        makeSystem(Terms1<A>.self, name: name, phase: phase, filter: filter, parallel: true) {
            Terms1<A>.forEach($0, body: body)
        }
    }

